1	"use client";
2	
3	// Real OpenAI `gpt-realtime-2` voice engine over a browser WebRTC peer connection.
4	//
5	// Architecture (no relay server): mint an ephemeral key at /api/openai/token,
6	// then negotiate WebRTC directly with OpenAI — POST the local SDP offer to
7	// https://api.openai.com/v1/realtime/calls (Authorization: Bearer <ephemeral>)
8	// and apply the answer. WebRTC handles ALL audio: the mic track is sent on the
9	// peer connection and the model's audio arrives on a remote track played by a
10	// hidden <audio> element. Barge-in truncation is handled server-side. Only
11	// session control + transcripts ride the `oai-events` data channel.
12	//
13	// Surface is deliberately identical to useXaiSession so useRealtimeSession can
14	// dispatch to either uniformly. Must be called unconditionally (rules of hooks);
15	// it stays inert until start().
16	
17	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
18	import type { Persona } from "@/lib/data";
19	import type { CallState, SessionTurn } from "./types";
20	import { resolveOpenaiAgent } from "./openai-agent";
21	
22	const CALLS_URL = "https://api.openai.com/v1/realtime/calls";
23	const VOL_GAIN = 3.5;
24	
25	export interface OpenaiSession {
26	  callState: CallState;
27	  turns: SessionTurn[];
28	  caption: string;
29	  start: () => void;
30	  stop: () => void;
31	  interrupt: () => void;
32	  setMuted: (muted: boolean) => void;
33	  getInputVolume: () => number;
34	  getOutputVolume: () => number;
35	}
36	
37	type OpenaiEvent = {
38	  type: string;
39	  delta?: string;
40	  transcript?: string;
41	  item_id?: string;
42	  response_id?: string;
43	  response?: { id?: string };
44	  error?: { type?: string; code?: string; message?: string };
45	};
46	
47	function extractToken(data: unknown): string | null {
48	  if (typeof data !== "object" || data === null) return null;
49	  const d = data as Record<string, unknown>;
50	  if (typeof d.value === "string") return d.value;
51	  if (typeof d.client_secret === "string") return d.client_secret;
52	  const cs = d.client_secret;
53	  if (cs && typeof cs === "object" && typeof (cs as Record<string, unknown>).value === "string") {
54	    return (cs as Record<string, unknown>).value as string;
55	  }
56	  return null;
57	}
58	
59	/** RMS of an analyser's current time-domain frame, scaled to a 0..1 orb level. */
60	function analyserLevel(
61	  analyser: AnalyserNode | null,
62	  buf: Float32Array<ArrayBuffer> | null,
63	): number {
64	  if (!analyser || !buf) return 0;
65	  analyser.getFloatTimeDomainData(buf);
66	  let sum = 0;
67	  for (let i = 0; i < buf.length; i++) sum += buf[i] * buf[i];
68	  return Math.min(1, Math.sqrt(sum / buf.length) * VOL_GAIN);
69	}
70	
71	export function useOpenaiSession(
72	  active: boolean,
73	  persona?: Persona,
74	  /**
75	   * Voice barge-in (settings INTERRUPTIONS): overrides the VAD presets'
76	   * `interrupt_response`. Default off — echo-safe on speaker+mic setups;
77	   * headphone users opt in to interrupt the agent by speaking.
78	   */
79	  bargeIn: boolean = false,
80	): OpenaiSession {
81	  const [callState, setCallState] = useState<CallState>("idle");
82	  const [turns, setTurns] = useState<SessionTurn[]>([]);
83	  const [caption, setCaption] = useState("press CALL to begin");
84	
85	  const pcRef = useRef<RTCPeerConnection | null>(null);
86	  const dcRef = useRef<RTCDataChannel | null>(null);
87	  const streamRef = useRef<MediaStream | null>(null);
88	  const audioElRef = useRef<HTMLAudioElement | null>(null);
89	
90	  // Web Audio analysers for orb levels (WebRTC keeps the audio bytes itself).
91	  const ctxRef = useRef<AudioContext | null>(null);
92	  const inAnalyserRef = useRef<AnalyserNode | null>(null);
93	  const outAnalyserRef = useRef<AnalyserNode | null>(null);
94	  const inBufRef = useRef<Float32Array<ArrayBuffer> | null>(null);
95	  const outBufRef = useRef<Float32Array<ArrayBuffer> | null>(null);
96	
97	  const mutedRef = useRef(false);
98	  // Half-duplex gate: with barge-in off, the mic track is silenced while agent
99	  // audio is playing so speaker leak can't reach the model at all.
100	  const micGatedRef = useRef(false);
101	  const endedRef = useRef(false);
102	  const configuredRef = useRef(false);
103	  const greetedRef = useRef(false);
104	
105	  const turnSeqRef = useRef(0);
106	  const agentResponseIdRef = useRef<string | null>(null);
107	  const cancelledAgentResponseIdsRef = useRef<Set<string>>(new Set());
108	  const suppressAgentDeltasRef = useRef(false);
109	  const agentTurnIdRef = useRef<string | null>(null);
110	  const agentBufRef = useRef("");
111	  const userTurnIdRef = useRef<string | null>(null);
112	  const userBufRef = useRef("");
113	  const interruptTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
114	  const stateRef = useRef<CallState>("idle");
115	  stateRef.current = callState;
116	  const personaRef = useRef(persona);
117	  personaRef.current = persona;
118	  const bargeInRef = useRef(bargeIn);
119	  bargeInRef.current = bargeIn;
120	
121	  const teardown = useCallback(() => {
122	    if (interruptTimerRef.current) {
123	      clearTimeout(interruptTimerRef.current);
124	      interruptTimerRef.current = null;
125	    }
126	    if (dcRef.current) {
127	      try {
128	        dcRef.current.close();
129	      } catch {
130	        // already closing
131	      }
132	      dcRef.current = null;
133	    }
134	    if (pcRef.current) {
135	      try {
136	        pcRef.current.close();
137	      } catch {
138	        // already closing
139	      }
140	      pcRef.current = null;
141	    }
142	    if (streamRef.current) {
143	      streamRef.current.getTracks().forEach((t) => t.stop());
144	      streamRef.current = null;
145	    }
146	    if (audioElRef.current) {
147	      audioElRef.current.srcObject = null;
148	      audioElRef.current = null;
149	    }
150	    if (ctxRef.current) {
151	      void ctxRef.current.close();
152	      ctxRef.current = null;
153	    }
154	    inAnalyserRef.current = null;
155	    outAnalyserRef.current = null;
156	    inBufRef.current = null;
157	    outBufRef.current = null;
158	    configuredRef.current = false;
159	    greetedRef.current = false;
160	    micGatedRef.current = false;
161	    agentResponseIdRef.current = null;
162	    cancelledAgentResponseIdsRef.current.clear();
163	    suppressAgentDeltasRef.current = false;
164	    agentTurnIdRef.current = null;
165	    agentBufRef.current = "";
166	    userTurnIdRef.current = null;
167	    userBufRef.current = "";
168	  }, []);
169	
170	  const send = useCallback((obj: unknown) => {
171	    const dc = dcRef.current;
172	    if (dc && dc.readyState === "open") dc.send(JSON.stringify(obj));
173	  }, []);
174	
175	  // User mute and the half-duplex gate compose onto the one mic track.
176	  // `enabled = false` makes WebRTC transmit silence — instant, no renegotiation.
177	  const applyMicEnabled = useCallback(() => {
178	    const enabled = !mutedRef.current && !micGatedRef.current;
179	    streamRef.current?.getAudioTracks().forEach((t) => (t.enabled = enabled));
180	  }, []);
181	
182	  const setMicGated = useCallback(
183	    (gated: boolean) => {
184	      micGatedRef.current = gated;
185	      applyMicEnabled();
186	    },
187	    [applyMicEnabled],
188	  );
189	
190	  // The setTurns updaters must stay PURE (no ref mutation inside): React
191	  // StrictMode double-invokes them, so id/sequence mutation happens here once.
192	  const beginAgentResponse = useCallback((responseId?: string) => {
193	    if (!responseId) return;
194	    agentResponseIdRef.current = responseId;
195	    cancelledAgentResponseIdsRef.current.delete(responseId);
196	    suppressAgentDeltasRef.current = false;
197	  }, []);
198	
199	  const shouldAcceptAgentDelta = useCallback((responseId?: string) => {
200	    if (suppressAgentDeltasRef.current) {
201	      if (!responseId || cancelledAgentResponseIdsRef.current.has(responseId)) return false;
202	      suppressAgentDeltasRef.current = false;
203	    }
204	    if (responseId && cancelledAgentResponseIdsRef.current.has(responseId)) return false;
205	    const activeResponseId = agentResponseIdRef.current;
206	    if (activeResponseId && responseId && activeResponseId !== responseId) return false;
207	    if (!activeResponseId && responseId) agentResponseIdRef.current = responseId;
208	    // A delta that survived the cancelled/suppress/id checks above belongs to a
209	    // live response — accept it even while the UI sits in the brief
210	    // "interrupted" window, or a fast reply after a barge-in loses its leading
211	    // text. Only unattributed deltas (no response id and no open turn) are
212	    // ambiguous enough to drop there: they may be the cancelled response's tail.
213	    if (stateRef.current !== "interrupted") return true;
214	    return !!responseId || !!agentTurnIdRef.current;
215	  }, []);
216	
217	  const cancelAgentResponse = useCallback(() => {
218	    const responseId = agentResponseIdRef.current;
219	    if (responseId) cancelledAgentResponseIdsRef.current.add(responseId);
220	    agentResponseIdRef.current = null;
221	    suppressAgentDeltasRef.current = true;
222	  }, []);
223	
224	  const pushAgentDelta = useCallback(
225	    (delta: string, responseId?: string) => {
226	      if (!shouldAcceptAgentDelta(responseId)) return;
227	      agentBufRef.current += delta;
228	      const text = agentBufRef.current;
229	      setCaption(text);
230	      let id = agentTurnIdRef.current;
231	      if (id) {
232	        const tid = id;
233	        setTurns((prev) => prev.map((t) => (t.id === tid ? { ...t, text } : t)));
234	      } else {
235	        id = `o${turnSeqRef.current++}`;
236	        agentTurnIdRef.current = id;
237	        const tid = id;
238	        setTurns((prev) => [...prev, { id: tid, who: "agent", text, live: true }]);
239	      }
240	    },
241	    [shouldAcceptAgentDelta],
242	  );
243	
244	  const finalizeAgent = useCallback((responseId?: string) => {
245	    if (responseId && cancelledAgentResponseIdsRef.current.has(responseId)) {
246	      if (agentResponseIdRef.current === responseId) agentResponseIdRef.current = null;
247	      return;
248	    }
249	    const activeResponseId = agentResponseIdRef.current;
250	    if (responseId && activeResponseId && responseId !== activeResponseId) {
251	      return;
252	    }
253	    const id = agentTurnIdRef.current;
254	    if (id) setTurns((prev) => prev.map((t) => (t.id === id ? { ...t, live: false } : t)));
255	    agentResponseIdRef.current = null;
256	    agentTurnIdRef.current = null;
257	    agentBufRef.current = "";
258	  }, []);
259	
260	  const start = useCallback(() => {
261	    if (stateRef.current !== "idle" && stateRef.current !== "ended") return;
262	    endedRef.current = false;
263	    configuredRef.current = false;
264	    greetedRef.current = false;
265	    setTurns([]);
266	    setCallState("connecting");
267	    setCaption("establishing session…");
268	
269	    const fail = (msg: string) => {
270	      endedRef.current = true;
271	      teardown();
272	      setCallState("ended");
273	      setCaption(msg);
274	    };
275	
276	    // ── transcript helpers ──────────────────────────────────────────────
277	    const pushUserDelta = (delta: string) => {
278	      userBufRef.current += delta;
279	      const text = userBufRef.current;
280	      setCaption(text);
281	      let id = userTurnIdRef.current;
282	      if (id) {
283	        const tid = id;
284	        setTurns((prev) => prev.map((t) => (t.id === tid ? { ...t, text } : t)));
285	      } else {
286	        id = `o${turnSeqRef.current++}`;
287	        userTurnIdRef.current = id;
288	        const tid = id;
289	        setTurns((prev) => [...prev, { id: tid, who: "user", text, live: true }]);
290	      }
291	    };
292	    const finalizeUser = (transcript: string) => {
293	      const text = transcript.trim();
294	      const id = userTurnIdRef.current;
295	      if (id) {
296	        setTurns((prev) =>
297	          prev.map((t) => (t.id === id ? { ...t, text: text || t.text, live: false } : t)),
298	        );
299	      } else if (text) {
300	        const tid = `o${turnSeqRef.current++}`;
301	        setTurns((prev) => [...prev, { id: tid, who: "user", text }]);
302	      }
303	      if (text) setCaption(text);
304	      userTurnIdRef.current = null;
305	      userBufRef.current = "";
306	    };
307	
308	    void (async () => {
309	      const agent = resolveOpenaiAgent(personaRef.current?.id);
310	
311	      // 1) Mic capture (also feeds the input analyser for the orb).
312	      let stream: MediaStream;
313	      try {
314	        stream = await navigator.mediaDevices.getUserMedia({
315	          audio: {
316	            channelCount: 1,
317	            echoCancellation: true,
318	            noiseSuppression: true,
319	            autoGainControl: true,
320	          },
321	        });
322	      } catch {
323	        fail("— microphone permission denied —");
324	        return;
325	      }
326	      if (endedRef.current) {
327	        stream.getTracks().forEach((t) => t.stop());
328	        return;
329	      }
330	      streamRef.current = stream;
331	      applyMicEnabled();
332	
333	      // 2) Analysers — input from the mic, output from the model's remote track.
334	      const ctx = new AudioContext();
335	      ctxRef.current = ctx;
336	      // The context only drives the level analysers (playback goes through the
337	      // <audio> element so Chrome's echo canceller keeps its reference signal),
338	      // but a suspended context still means dead orb meters.
339	      if (ctx.state === "suspended") await ctx.resume();
340	      const inAnalyser = ctx.createAnalyser();
341	      inAnalyser.fftSize = 1024;
342	      ctx.createMediaStreamSource(stream).connect(inAnalyser);
343	      inAnalyserRef.current = inAnalyser;
344	      inBufRef.current = new Float32Array(inAnalyser.fftSize);
345	
346	      // 3) Peer connection + remote audio playback.
347	      const pc = new RTCPeerConnection();
348	      pcRef.current = pc;
349	      const audioEl = document.createElement("audio");
350	      audioEl.autoplay = true;
351	      audioEl.setAttribute("playsinline", "true");
352	      audioEl.setAttribute("webkit-playsinline", "true");
353	      audioElRef.current = audioEl;
354	      pc.ontrack = (e) => {
355	        const [remote] = e.streams;
356	        if (!remote) return;
357	        // Keep the analyser's context alive — e.g. after an iOS audio interruption.
358	        if (ctx.state === "suspended") void ctx.resume();
359	        // Play the element DIRECTLY — do not route it through the AudioContext
360	        // (createMediaElementSource → destination). Chrome's echo canceller uses
361	        // directly-played remote WebRTC audio as its reference; rerouting through
362	        // Web Audio bypasses AEC and the speakers feed the model back to itself.
363	        audioEl.srcObject = remote;
364	        void audioEl.play().catch(() => {
365	          // autoplay policy can defer playback; the element remains wired
366	        });
367	        // Passive tap on the remote stream for the orb level only (never connected
368	        // to destination — the element owns playback). Chrome keeps this analyser
369	        // fed as long as the same stream is attached to a playing media element.
370	        try {
371	          const outAnalyser = ctx.createAnalyser();
372	          outAnalyser.fftSize = 1024;
373	          ctx.createMediaStreamSource(remote).connect(outAnalyser);
374	          outAnalyserRef.current = outAnalyser;
375	          outBufRef.current = new Float32Array(outAnalyser.fftSize);
376	        } catch {
377	          // analyser is best-effort; playback still works without it
378	        }
379	      };
380	      stream.getTracks().forEach((t) => pc.addTrack(t, stream));
381	
382	      // 4) Data channel for session control + transcript events.
383	      const dc = pc.createDataChannel("oai-events");
384	      dcRef.current = dc;
385	
386	      const configure = () => {
387	        if (configuredRef.current) return;
388	        configuredRef.current = true;
389	        // Voice is locked after the first audio output, so set it now, before any
390	        // response. reasoning.effort nests under session, per the lifecycle docs.
391	        send({
392	          type: "session.update",
393	          session: {
394	            type: "realtime",
395	            model: agent.model,
396	            output_modalities: ["audio"],
397	            instructions: agent.instructions,
398	            audio: {
399	              input: {
400	                // The settings INTERRUPTIONS toggle decides barge-in, not the preset.
401	                turn_detection: { ...agent.turnDetection, interrupt_response: bargeInRef.current },
402	                transcription: agent.transcription,
403	              },
404	              output: { voice: agent.voice },
405	            },
406	            reasoning: { effort: agent.reasoningEffort },
407	          },
408	        });
409	      };
410	
411	      const greet = () => {
412	        if (greetedRef.current) return;
413	        greetedRef.current = true;
414	        setCallState("listening");
415	        setCaption("listening…");
416	        send({
417	          type: "conversation.item.create",
418	          item: {
419	            type: "message",
420	            role: "user",
421	            content: [{ type: "input_text", text: agent.firstMessage }],
422	          },
423	        });
424	        send({ type: "response.create" });
425	      };
426	
427	      dc.onopen = () => {
428	        if (endedRef.current) return;
429	        configure();
430	      };
431	
432	      dc.onmessage = (event) => {
433	        if (endedRef.current) return;
434	        let msg: OpenaiEvent;
435	        try {
436	          msg = JSON.parse(typeof event.data === "string" ? event.data : "") as OpenaiEvent;
437	        } catch {
438	          return;
439	        }
440	        switch (msg.type) {
441	          case "session.created":
442	            configure();
443	            break;
444	          case "session.updated":
445	            greet();
446	            break;
447	          case "response.created":
448	            beginAgentResponse(msg.response?.id ?? msg.response_id);
449	            if (stateRef.current !== "interrupted") setCallState("speaking");
450	            break;
451	          case "response.output_audio_transcript.delta":
452	            if (msg.delta) {
453	              if (stateRef.current !== "interrupted") setCallState("speaking");
454	              pushAgentDelta(msg.delta, msg.response_id);
455	            }
456	            break;
457	          case "response.done":
458	            finalizeAgent(msg.response?.id ?? msg.response_id);
459	            if (stateRef.current === "speaking") setCallState("listening");
460	            break;
461	          case "input_audio_buffer.speech_started":
462	            // With barge-in on (`interrupt_response: true`) the server truncates
463	            // the model's audio for us on WebRTC — reflect the interruption in
464	            // the UI. With it off (the echo-safe default) this event is usually
465	            // the model's own leaked playback, so don't fake an interruption
466	            // that isn't happening; interrupting is the manual button.
467	            if (bargeInRef.current) {
468	              cancelAgentResponse();
469	              finalizeAgent();
470	              setCallState("interrupted");
471	              if (interruptTimerRef.current) clearTimeout(interruptTimerRef.current);
472	              interruptTimerRef.current = setTimeout(() => setCallState("listening"), 600);
473	            }
474	            break;
475	          case "input_audio_buffer.speech_stopped":
476	          case "input_audio_buffer.committed":
477	            if (stateRef.current === "interrupted") setCallState("listening");
478	            break;
479	          case "output_audio_buffer.started":
480	            // Agent audio is now playing (WebRTC-only event). With barge-in off,
481	            // go half-duplex: silence the mic so speaker leak can't be committed
482	            // as a user turn and answered. With barge-in on, the mic stays open
483	            // so the user can talk over the agent.
484	            if (!bargeInRef.current) setMicGated(true);
485	            break;
486	          case "output_audio_buffer.stopped":
487	          case "output_audio_buffer.cleared":
488	            // Playback drained (or was cleared by interrupt) — reopen the mic.
489	            // Gate off here rather than at response.done: generation finishes
490	            // while the audio tail is still playing, and that tail is the echo.
491	            setMicGated(false);
492	            break;
493	          case "conversation.item.input_audio_transcription.delta":
494	            if (msg.delta) pushUserDelta(msg.delta);
495	            break;
496	          case "conversation.item.input_audio_transcription.completed":
497	            finalizeUser(msg.transcript ?? "");
498	            break;
499	          case "error":
500	            setCaption(`— ${msg.error?.message ?? "OpenAI error"} —`);
501	            break;
502	          default:
503	            break;
504	        }
505	      };
506	
507	      // 5) Mint the ephemeral key, then exchange SDP with OpenAI.
508	      let token: string | null = null;
509	      try {
510	        const res = await fetch("/api/openai/token", { method: "POST" });
511	        const data = await res.json();
512	        if (!res.ok) {
513	          fail(`— ${typeof data?.error === "string" ? data.error : "token error"} —`);
514	          return;
515	        }
516	        token = extractToken(data);
517	      } catch {
518	        fail("— could not reach token endpoint —");
519	        return;
520	      }
521	      if (!token) {
522	        fail("— no OpenAI token returned —");
523	        return;
524	      }
525	      if (endedRef.current) return;
526	
527	      try {
528	        const offer = await pc.createOffer();
529	        await pc.setLocalDescription(offer);
530	        const sdpRes = await fetch(CALLS_URL, {
531	          method: "POST",
532	          body: offer.sdp,
533	          headers: {
534	            Authorization: `Bearer ${token}`,
535	            "Content-Type": "application/sdp",
536	          },
537	        });
538	        if (!sdpRes.ok) {
539	          fail(`— OpenAI call setup failed (${sdpRes.status}) —`);
540	          return;
541	        }
542	        const answer: RTCSessionDescriptionInit = { type: "answer", sdp: await sdpRes.text() };
543	        if (endedRef.current) return;
544	        await pc.setRemoteDescription(answer);
545	      } catch {
546	        fail("— could not establish WebRTC session —");
547	        return;
548	      }
549	    })();
550	  }, [
551	    applyMicEnabled,
552	    beginAgentResponse,
553	    cancelAgentResponse,
554	    finalizeAgent,
555	    pushAgentDelta,
556	    send,
557	    setMicGated,
558	    teardown,
559	  ]);
560	
561	  const stop = useCallback(() => {
562	    endedRef.current = true;
563	    teardown();
564	    setCallState("ended");
565	    setCaption("— call ended —");
566	  }, [teardown]);
567	
568	  const interrupt = useCallback(() => {
569	    if (stateRef.current !== "speaking") return;
570	    // Cancel the in-progress response and clear any unplayed server audio.
571	    send({ type: "response.cancel" });
572	    send({ type: "output_audio_buffer.clear" });
573	    cancelAgentResponse();
574	    finalizeAgent();
575	    setCallState("interrupted");
576	    if (interruptTimerRef.current) clearTimeout(interruptTimerRef.current);
577	    interruptTimerRef.current = setTimeout(() => setCallState("listening"), 600);
578	  }, [cancelAgentResponse, finalizeAgent, send]);
579	
580	  const setMuted = useCallback(
581	    (muted: boolean) => {
582	      mutedRef.current = muted;
583	      applyMicEnabled();
584	    },
585	    [applyMicEnabled],
586	  );
587	
588	  const getInputVolume = useCallback(() => {
589	    if (mutedRef.current) return 0;
590	    return analyserLevel(inAnalyserRef.current, inBufRef.current);
591	  }, []);
592	  const getOutputVolume = useCallback(
593	    () => analyserLevel(outAnalyserRef.current, outBufRef.current),
594	    [],
595	  );
596	
